import {AcmeSpinner} from '/Users/peterkloss/Dev/ACMElabs/design-system/src/components/spinner/spinner';
import {AcmeIconTile} from '/Users/peterkloss/Dev/ACMElabs/design-system/src/components/icon-tile/icon-tile';
const owned=new WeakMap<object,Set<object>>();
class ObservedSpinner extends AcmeSpinner { addController(controller:any){let controllers=owned.get(this);if(!controllers){controllers=new Set();owned.set(this,controllers);}controllers.add(controller);super.addController(controller);} removeController(controller:any){owned.get(this)?.delete(controller);super.removeController(controller);} }
customElements.define("acme-spinner",ObservedSpinner);customElements.define('acme-icon-tile',AcmeIconTile);
const results:any[]=[];const check=(name:string,ok:boolean,actual?:unknown)=>results.push({name,ok,...(!ok?{actual}:{})});const wait=()=>new Promise(r=>setTimeout(r,80));
try{
 const spinner=new ObservedSpinner();spinner.id='spinner';document.body.append(spinner);await spinner.updateComplete;await wait();
 const animations=()=>spinner.shadowRoot!.getAnimations();
 check('medium Spinner has ten owned opacity animations',animations().length===10&&animations().every(a=>(a.effect as KeyframeEffect).getKeyframes().every(f=>f.transform===undefined)),animations().length);
 const before=animations()[0]?.currentTime;await wait();check('native animation time advances',Number(animations()[0]?.currentTime)>Number(before));
 spinner.label='Loading projects';await spinner.updateComplete;await wait();check('label changes retain exactly one animation per blade',animations().length===10&&spinner.shadowRoot!.querySelector('[role=status]')?.textContent?.trim()==='Loading projects');
 for(const [size,width,count]of [['small',12,8],['medium',16,10],['large',20,12],['extraLarge',24,12],['extraExtraLarge',32,15]] as const){spinner.size=size;await spinner.updateComplete;await wait();const box=spinner.shadowRoot!.querySelector('[part=root]')!.getBoundingClientRect();check(size+' retains its source dimensions and blade count',box.width===width&&box.height===width&&animations().length===count,{width:box.width,height:box.height,animations:animations().length});}
 const initialControllers=owned.get(spinner)!.size;for(let i=0;i<20;i++){spinner.size=i%2?"extraExtraLarge":"small";await spinner.updateComplete;await wait();}check("repeated resizing keeps controller ownership bounded",owned.get(spinner)!.size===initialControllers,{before:initialControllers,after:owned.get(spinner)!.size});
 const running=animations();spinner.remove();await wait();check('disconnect cancels every owned animation',running.every(animation=>animation.playState==='idle'));document.body.append(spinner);await spinner.updateComplete;await wait();check('reconnect starts the current blade set once',animations().length===15);
 const frame=document.createElement('iframe');document.body.append(frame);frame.contentDocument!.body.append(spinner);await spinner.updateComplete;await wait();check('document adoption restarts the current animation set',animations().length===15);
 document.body.append(spinner);await spinner.updateComplete;await wait();
 const tile=new AcmeIconTile();tile.innerHTML='<span role="img" aria-label="Project">P</span>';document.body.append(tile);await tile.updateComplete;check('Icon Tile preserves the authored image semantics',!tile.shadowRoot!.querySelector('[part=root]')!.hasAttribute('aria-hidden'));
 tile.size='64px';await tile.updateComplete;const box=tile.getBoundingClientRect(),surface=tile.shadowRoot!.querySelector('[part=root]')!.getBoundingClientRect();check('Icon Tile dimensions include one padding and border charge',box.width===64&&box.height===64&&surface.width===64&&surface.height===64,{host:[box.width,box.height],surface:[surface.width,surface.height]});
 (window as any).__spinner=spinner;(window as any).__results={results};
}catch(error){(window as any).__results={results,error:String(error),stack:(error as Error).stack}}

